    if (who() && (isReturning || daysAway >= 1) && Math.random() < 0.5) { nameAt = activeMs(); return { t: say1("openName") }; }   // "ah, {name}, ya te conozco"
    if (daysAway >= 2) return { t: say1("openLongAway", { d: daysAway }), mood: "angry" };
    const lr = DS.lastRun;
    if (lr && isReturning && Math.random() < 0.75) return { t: say1(lr.won ? "openLastWin" : "openLastLose", { r: lr.r }) };
